'use strict';
// Geological stages are a sandbox timescale, independent of civilization technology.
const eraOrder=['carboniferous','jurassic','cretaceous','ice','holocene'];
const eraDefs={carboniferous:{name:'Kỷ Than đá',icon:'🌿',text:'Rừng ẩm và đầm lầy. Những vỉa than hữu hạn xuất hiện dưới rừng.',animals:[],growth:1.25},jurassic:{name:'Kỷ Jura',icon:'🦕',text:'Môi trường ấm, rừng cổ đại; Stegosaurus và khủng long săn mồi xuất hiện.',animals:['stego','allosaur'],growth:1.15},cretaceous:{name:'Kỷ Phấn trắng',icon:'🦖',text:'Rừng nhiệt đới, vùng khô và Triceratops. Sinh vật cổ sống cùng các tộc trong sandbox.',animals:['triceratops','raptor'],growth:1.1},ice:{name:'Thời Băng hà',icon:'❄️',text:'Lãnh nguyên và rừng lạnh mở rộng. Cây cỏ mọc chậm; cư dân cần nơi trú tuyết.',animals:['mammoth','saber'],growth:.35},holocene:{name:'Holocen',icon:'🌱',text:'Khí hậu ôn hòa hơn. Các vùng môi trường và nền văn minh tiếp tục phát triển.',animals:[],growth:1}};
const biomeDefs={plains:{name:'Đồng cỏ',icon:'🌱',color:'#68a66a',growth:1},jungle:{name:'Rừng nhiệt đới',icon:'🌴',color:'#398858',growth:1.35},desert:{name:'Sa mạc',icon:'🌵',color:'#dbbd80',growth:.3},taiga:{name:'Rừng lạnh',icon:'🌲',color:'#69968e',growth:.65},tundra:{name:'Lãnh nguyên',icon:'❄️',color:'#c2dbe0',growth:.25},swamp:{name:'Đầm lầy',icon:'🪷',color:'#527e68',growth:1.15},mountain:{name:'Núi đá',icon:'⛰️',color:'#929fa5',growth:0},ocean:{name:'Đại dương',icon:'🌊',color:'#16425b',growth:0}};
const ancientDefs={stego:{name:'Stegosaurus',kind:'sheep',period:'jurassic',pace:.8,habitats:['jungle','swamp','plains'],color:'#82b879'},allosaur:{name:'Khủng long săn mồi Jura',kind:'wolf',period:'jurassic',pace:1.05,habitats:['jungle','plains'],color:'#b27d61'},triceratops:{name:'Triceratops',kind:'sheep',period:'cretaceous',pace:.85,habitats:['jungle','plains'],color:'#92b0ba'},raptor:{name:'Khủng long săn mồi Phấn trắng',kind:'wolf',period:'cretaceous',pace:1.2,habitats:['jungle','desert','plains'],color:'#bdad6a'},mammoth:{name:'Voi ma mút',kind:'sheep',period:'ice',pace:.7,habitats:['tundra','taiga'],color:'#b3957c'},saber:{name:'Thú răng kiếm',kind:'wolf',period:'ice',pace:1.1,habitats:['tundra','taiga','plains'],color:'#dac59c'}};
let geology={current:'carboniferous',auto:true,elapsed:0,daysPerEra:30,visited:[],fossils:[],found:0,wildlifeTick:0},biomeCache=new Uint8Array(N),biomeEpoch=-1,biomeEra='',eraTick=0,eraHudSignature='';
const biomeKeys=Object.keys(biomeDefs),eraOld={simulate,ecology,newWorld,restore,snapshot,applyTool,showSelection,drawCreature,animal:planAnimal,rollWeather,weatherAt,renderEconomy};
function environmentHash(i){return ((Math.imul(i+1,1103515245)^Math.floor(grid[i].shade*1e6))>>>0)%1000/1000;}
function refreshBiomes(){if(biomeEpoch===terrainEpoch&&biomeEra===geology.current)return;for(let i=0;i<N;i++){const t=grid[i],x=i%W,y=Math.floor(i/W),wave=Math.sin(x*.075+y*.031)+Math.cos(y*.11-x*.04),wet=Math.sin(x*.10-y*.035)+Math.cos(x*.029+y*.12);let biome=t.t===0?'ocean':t.t===4?'mountain':t.biome;if(!biome){if(geology.current==='ice')biome=wave>.2?'taiga':'tundra';else if(geology.current==='carboniferous')biome=wet>.35?'swamp':t.t===3?'jungle':'plains';else if(geology.current==='jurassic'||geology.current==='cretaceous')biome=wave<-1?'desert':wet>.9?'swamp':t.t===3||wave>.25?'jungle':'plains';else biome=wave<-1.1?'desert':wave>1.3?'taiga':wet>1.4?'swamp':t.t===3?'jungle':'plains';}biomeCache[i]=biomeKeys.indexOf(biome);}biomeEpoch=terrainEpoch;biomeEra=geology.current;}
function biomeAt(x,y){if(!inside(x,y))return'ocean';refreshBiomes();return biomeKeys[biomeCache[idx(x,y)]];}
function terrainColorAt(x,y,t){const biome=biomeAt(x,y);if(t.t===0)return colors[0];if(t.t===4)return geology.current==='ice'?'#b3cbd1':colors[4];if(t.t===5)return biome==='tundra'?'#a7c2b2':'#8ab966';if(t.t===2&&biome==='plains')return colors[2];return biomeDefs[biome].color;}
function paintBiomeObject(c,x,y,t){if(![0,1].includes(t.obj))return false;const b=biomeAt(x,y);if(b==='jungle'&&geology.current!=='holocene'){c.fillStyle='#876a44';c.fillRect(x+.4,y-1,.25,1.7);c.fillStyle='#255e46';c.fillRect(x-.2,y-1.7,1.5,.75);c.fillStyle='#4caa6c';c.fillRect(x-.4,y-1.5,1.8,.35);c.fillRect(x+.2,y-2,.8,.6);return true;}if(['taiga','tundra'].includes(b)){c.fillStyle='#766f60';c.fillRect(x+.44,y-.4,.2,1.1);c.fillStyle='#285d59';c.fillRect(x+.24,y-1.8,.6,.45);c.fillRect(x,y-1.35,1.1,.45);c.fillRect(x-.2,y-.9,1.5,.65);if(geology.current==='ice'||b==='tundra'){c.fillStyle='#d7ecee';c.fillRect(x+.24,y-1.8,.6,.15);c.fillRect(x,y-1.35,1.1,.15);c.fillRect(x-.2,y-.9,1.5,.16);}return true;}if(b==='desert'){c.fillStyle='#599270';c.fillRect(x+.38,y-1.1,.3,1.8);c.fillRect(x+.04,y-.65,.7,.2);c.fillRect(x+.04,y-1,.18,.4);return true;}return false;}
function paintEraScenery(c){for(const f of geology.fossils)if(f.amount>0&&grid[f.index].t!==0){const x=f.index%W,y=Math.floor(f.index/W);c.fillStyle='#eadbc0';c.fillRect(x+.13,y+.35,.7,.14);c.fillRect(x+.13,y+.22,.15,.4);c.fillRect(x+.68,y+.22,.15,.4);}if(geology.current==='carboniferous')for(let i=0;i<N;i+=3)if(biomeCache[i]===biomeKeys.indexOf('swamp')&&grid[i].t!==0){const x=i%W,y=Math.floor(i/W);c.fillStyle='#3c695e88';c.fillRect(x+.15,y+.65,.7,.1);}}
function seedEraDeposits(){if(geology.visited.includes(geology.current))return;geology.visited.push(geology.current);let placed=0,coal=0;for(let i=0;i<N;i++){const t=grid[i],h=environmentHash(i);if(t.t===0)continue;if(geology.fossils.length<120&&placed<15&&(t.ore||t.t===4)&&h<.22&&!geology.fossils.some(f=>f.index===i)){geology.fossils.push({index:i,amount:3+Math.floor(h*20),period:geology.current});placed++;}if(geology.current==='carboniferous'&&t.t===3&&!t.ore&&h<.05&&coal<15){t.ore={type:'coal',amount:65,initial:65};coal++;}}mapDirty=true;}
function spawnAncient(species,x,y){const def=ancientDefs[species];if(!def||!walkable(x,y))return null;const e=spawn(def.kind,x,y);if(e){e.species=species;e.name=def.name;e.hunger=85;motionFor(e).pace=def.pace;}return e;}
function seedEraWildlife(){for(const species of eraDefs[geology.current].animals){const desired=ancientDefs[species].kind==='sheep'?4:2,count=entities.filter(e=>e.species===species).length;for(let n=count;n<desired;n++){const start=(n*1237+eraOrder.indexOf(geology.current)*457)%N;let p=null;for(let k=0;k<N;k++){const i=(start+k*17)%N,x=i%W+.5,y=Math.floor(i/W)+.5;if(walkable(x,y)&&ancientDefs[species].habitats.includes(biomeAt(x,y))&&villages.every(v=>Math.hypot(v.x-x,v.y-y)>9)){p={x,y};break;}}if(p)spawnAncient(species,p.x,p.y);}}indexResidents();}
function setGeologicalEra(period){if(!Object.hasOwn(eraDefs,period))throw Error('Thời kỳ không hợp lệ.');if(geology.current===period)return;geology.current=period;geology.elapsed=0;biomeEpoch=-1;terrainEpoch++;routeFields.clear();mapDirty=true;seedEraDeposits();seedEraWildlife();refreshWeather(false);remember('Thế giới bước vào '+eraDefs[period].name+'.','civil');renderEraHud();if($('era-dialog').open)renderEraPanel();}
function nextGeologicalEra(){const i=eraOrder.indexOf(geology.current);if(i<eraOrder.length-1)setGeologicalEra(eraOrder[i+1]);}
function getGeology(){refreshBiomes();const distribution={};for(let i=0;i<N;i++)distribution[biomeKeys[biomeCache[i]]]=(distribution[biomeKeys[biomeCache[i]]]||0)+1;return{current:geology.current,name:eraDefs[geology.current].name,auto:geology.auto,daysPerEra:geology.daysPerEra,daysElapsed:geology.elapsed/GAME_DAY_SECONDS,found:geology.found,deposits:geology.fossils.filter(f=>f.amount>0).length,wildlife:entities.filter(e=>e.species).map(e=>({id:e.id,species:e.species,name:e.name})),biomes:distribution};}
rollWeather=function(season){if(geology.current==='ice'){const list=season===1?['snow','cloud','wind','rain','clear']:['snow','snow','snow','wind','cloud'];return list[Math.floor(random()*list.length)];}if(['carboniferous','jurassic','cretaceous'].includes(geology.current)&&season===3){const list=['rain','rain','cloud','wind','clear'];return list[Math.floor(random()*list.length)];}return eraOld.rollWeather(season);};
weatherAt=function(x,y){const type=eraOld.weatherAt(x,y);if(!climate.enabled)return type;const b=biomeAt(x,y);if(geology.current==='ice'&&b==='tundra'&&['clear','cloud','wind'].includes(type))return'snow';return type;};
ecology=function(){eraOld.ecology();refreshBiomes();for(let i=0;i<N;i++){const t=grid[i];if(t.t===0||t.t===4||t.fire)continue;const growth=biomeDefs[biomeKeys[biomeCache[i]]].growth*eraDefs[geology.current].growth,max=t.t===5?45:t.t===3?20:t.obj===3?25:6;t.food=Math.max(0,Math.min(max,t.food+.4*(growth-1)));}for(const e of humans())if(e.job==='miner'&&isOnDuty(e)&&e.village&&simTime>=(mindFor(e).fossilAt||0)){const f=geology.fossils.find(f=>f.amount>0&&Math.hypot(f.index%W+.5-e.x,Math.floor(f.index/W)+.5-e.y)<1.8);if(f){f.amount--;geology.found++;const v=villages.find(v=>v.id===e.village);if(v)v.knowledge=Math.min(2000,v.knowledge+.02);mindFor(e).fossilAt=simTime+10;mapDirty=true;}}};
simulate=function(dt){eraOld.simulate(dt);geology.elapsed=Math.min(geology.daysPerEra*GAME_DAY_SECONDS,geology.elapsed+dt);geology.wildlifeTick+=dt;eraTick+=dt;if(geology.auto&&geology.elapsed>=geology.daysPerEra*GAME_DAY_SECONDS)nextGeologicalEra();if(geology.wildlifeTick>=60){geology.wildlifeTick%=60;seedEraWildlife();}if(eraTick>=1){eraTick%=1;renderEraHud();}};
planAnimal=function(e){eraOld.animal(e);const def=ancientDefs[e.species];if(!def)return;motionFor(e).pace=def.pace;const m=mindFor(e);if(e.hunger>80&&m.type==='wander'&&!def.habitats.includes(biomeAt(e.x,e.y))&&simTime>=(m.habitatAt||0)){m.habitatAt=simTime+20;const target=nearestTile(e,(t,x,y)=>def.habitats.includes(biomeAt(x,y))&&!t.fire,10);if(target)go(e,target,'migrate',25);}};purposeNames.migrate='Tìm môi trường phù hợp';
applyTool=function(x,y){if(!inside(x,y))return;if(tool.startsWith('biome-')){const biome=tool.slice(6);if(!Object.hasOwn(biomeDefs,biome)||['ocean','mountain'].includes(biome))return;for(let yy=Math.max(0,Math.floor(y-radius));yy<Math.min(H,y+radius+1);yy++)for(let xx=Math.max(0,Math.floor(x-radius));xx<Math.min(W,x+radius+1);xx++)if(Math.hypot(xx+.5-x,yy+.5-y)<=radius&&![0,4].includes(grid[idx(xx,yy)].t)){const t=grid[idx(xx,yy)];t.biome=biome;if(biome==='desert')Object.assign(t,{t:2,obj:-1,food:2,fire:0});else if(['jungle','taiga'].includes(biome))Object.assign(t,{t:3,obj:xx%2,food:20,fire:0});else Object.assign(t,{t:1,obj:-1,food:6,fire:0});}biomeEpoch=-1;terrainEpoch++;mapDirty=true;routeFields.clear();return;}if(tool.startsWith('ancient-')){if(!spawnAncient(tool.slice(8),x,y))toast('Thả sinh vật trên đất trống.');updateStats();return;}if(tool==='fossil-find'){let found=0;for(const f of geology.fossils)if(f.amount>0&&Math.hypot(f.index%W+.5-x,Math.floor(f.index/W)+.5-y)<=radius+1){f.amount--;found++;}if(found){geology.found+=found;effect('bless',x,y,radius);mapDirty=true;toast('Khám phá '+found+' mẫu hóa thạch.');}else toast('Tìm dấu xương gần núi hoặc mỏ khoáng sản.');renderEraHud();return;}eraOld.applyTool(x,y);if(['land','water','sand','forest','mountain','wheat'].includes(tool)){for(let yy=Math.max(0,Math.floor(y-radius));yy<Math.min(H,y+radius+1);yy++)for(let xx=Math.max(0,Math.floor(x-radius));xx<Math.min(W,x+radius+1);xx++)if(Math.hypot(xx+.5-x,yy+.5-y)<=radius)delete grid[idx(xx,yy)].biome;biomeEpoch=-1;mapDirty=true;}};
showSelection=function(id){eraOld.showSelection(id);const e=entities.find(e=>e.id===id);if(!e)return;const p=document.createElement('p');p.textContent=biomeDefs[biomeAt(e.x,e.y)].icon+' Môi trường: '+biomeDefs[biomeAt(e.x,e.y)].name+(e.species?' · '+eraDefs[ancientDefs[e.species].period].name:'');$('selection').append(p);};
function freshGeology(current='carboniferous',auto=true){geology={current,auto,elapsed:0,daysPerEra:30,visited:[],fossils:[],found:0,wildlifeTick:0};biomeEpoch=-1;eraTick=0;eraHudSignature='';seedEraDeposits();seedEraWildlife();}
newWorld=function(...args){eraOld.newWorld(...args);freshGeology(Object.hasOwn(eraDefs,$('new-era').value)?$('new-era').value:'carboniferous');refreshWeather(false);renderEraHud();};
snapshot=function(){return{...eraOld.snapshot(),version:8,geology:JSON.parse(JSON.stringify(geology))};};
function validateGeology(d){const g=d.geology,finite=(v,max)=>typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=max;if(!g||!Object.hasOwn(eraDefs,g.current)||typeof g.auto!=='boolean'||g.daysPerEra!==30||!finite(g.elapsed,30*GAME_DAY_SECONDS)||!finite(g.wildlifeTick,60)||!Number.isInteger(g.found)||g.found<0||g.found>1e8||!Array.isArray(g.visited)||g.visited.length>5||new Set(g.visited).size!==g.visited.length||!g.visited.every(p=>Object.hasOwn(eraDefs,p))||!Array.isArray(g.fossils)||g.fossils.length>120||new Set(g.fossils.map(f=>f.index)).size!==g.fossils.length||!g.fossils.every(f=>Number.isInteger(f.index)&&f.index>=0&&f.index<N&&Number.isInteger(f.amount)&&f.amount>=0&&f.amount<=10&&Object.hasOwn(eraDefs,f.period)))throw Error('Dữ liệu thời kỳ không hợp lệ.');}
restore=function(input){const d=JSON.parse(JSON.stringify(input));if(!d||!Array.isArray(d.grid)||!Array.isArray(d.entities))throw Error('Tệp thế giới không hợp lệ.');if(!d.grid.every(t=>t.biome===undefined||Object.hasOwn(biomeDefs,t.biome)&&!['ocean','mountain'].includes(t.biome))||!d.entities.every(e=>e.species===undefined||Object.hasOwn(ancientDefs,e.species)&&ancientDefs[e.species].kind===e.kind))throw Error('Môi trường hoặc sinh vật cổ không hợp lệ.');const version=d.version;if(version===8){validateGeology(d);d.version=7;}eraOld.restore(d);if(version===8)geology=d.geology;else freshGeology('holocene',false);biomeEpoch=-1;eraHudSignature='';mapDirty=true;for(const e of entities)if(e.species)motionFor(e).pace=ancientDefs[e.species].pace;renderEraHud();};
window.mamWorld={...window.mamWorld,newWorld:(...a)=>newWorld(...a),simulate:dt=>simulate(dt),ecology:()=>ecology(),applyTool:(...a)=>applyTool(...a),snapshot:()=>snapshot(),restore:d=>restore(d),getGeology,setGeologicalEra,nextGeologicalEra};
